#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"//// Структураtypedef struct : public SPROLOZ  {   int nNumberYellow;   int nNumberRed;  } Queue_AlarmRect;// Функция отображенияint PaintAlarmRect(DefinePaint)  {  QueueP(Queue_AlarmRect);  //  bool bDrawYellow=false;  bool bDrawRed=false;  COLORREF clrRed=RGB(255,0,0);  COLORREF clrYellow=RGB(255,255,0);  COLORREF clrTrans=RGB(255,255,255);  RECT rc = p->mRect;  if ( p->nNumberRed >= 0 )  {	  CShHS& Sh = (CShHS&)q.m_pPipe->SH(p->nNumberRed);      if ( Sh.RetCode == CShBase::rcOK )			bDrawRed = Sh.mOn;  }  if (!bDrawRed)  {	  if ( p->nNumberYellow >= 0 )	  {		  CShHS& Sh = (CShHS&)q.m_pPipe->SH(p->nNumberYellow);		  if ( Sh.RetCode == CShBase::rcOK )				bDrawYellow = Sh.mOn;	  }  }  if (bDrawRed)		::TransparentRect( hDC, p->mRect, clrRed, clrTrans );  else	  if (bDrawYellow)		::TransparentRect( hDC, p->mRect, clrYellow, clrTrans );  return 0;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddAlarmRect(DefineTegs)  {  //  AddQueueEx(Queue_AlarmRect);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintAlarmRect;  //  p->nNumberYellow=-1;  p->nNumberRed=-1;  //  char szHsNameYellow[64]="";  char szHsNameRed[64]="";  //  STegObj obj[] =    {    { 'R', "rect"   , &p->mRect  },    { 'E', "rc"     , &p->mRect  },	{ 'S', "hsNameYellow", szHsNameYellow, 63 },	{ 'S', "hsNameRed", szHsNameRed, 63 },    EXT_QUEUE  // Дополнительная информация    //    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  if (*szHsNameYellow)	  p->nNumberYellow=def.AddKind( id_HS    , szHsNameYellow );  if (*szHsNameRed)	  p->nNumberRed=def.AddKind( id_HS    , szHsNameRed );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~